USD rates:\nrate_1949 = (8 * (1/4.03) + 4 * (1/2.80)) / 12\nprint(f\"1949 average GBP per USD: {rate_1949:.6f}\")\n\n# For 1950: all 12 months at $2.80/£ → $1 = £(1/2.80) = £0.3571\nrate_1950 = 1 / 2.80\nprint(f\"1950 average GBP per USD: {rate_1950:.6f}\")\n\n# For 1951: all 12 months at $2.80/£ → $1 = £(1/2.80) = £0.3571\nrate_1951 = 1 / 2.80\nprint(f\"1951 average GBP per USD: {rate_1951:.6f}\")\n\n# Now calculate the debt totals in millions USD\nsubtotal_1950 = 154764 + 66771  # 221,535\nsubtotal_1951 = 151625 + 67824  # 219,449\nsubtotal_1952 = 142701 + 79075  # 221,776\n\nprint(f\"\\nSubtotals (millions USD):\")\nprint(f\"Feb 28, 1950: {subtotal_1950}\")\nprint(f\"Feb 28, 1951: {subtotal_1951}\")\nprint(f\"Feb 29, 1952: {subtotal_1952}\")\n\n# Convert to GBP (millions)\ngbp_1950 = subtotal_1950 * rate_1949\ngbp_1951 = subtotal_1951 * rate_1950\ngbp_1952 = subtotal_1952 * rate_1951\n\nprint(f\"\\nConverted to GBP (millions):\")\nprint(f\"Feb 28, 1950: {gbp_1950:.2f}\")\nprint(f\"Feb 28, 1951: {gbp_1951:.2f}\")\nprint(f\"Feb 29, 1952: {gbp_1952:.2f}\")\n\n# Total and convert to billions\ntotal_gbp_millions = gbp_1950 + gbp_1951 + gbp_1952\ntotal_gbp_billions = total_gbp_millions / 1000\n\nprint(f\"\\n=== Final Result ===\")\nprint(f\"Total: {total_gbp_billions:.1f} billion GBP\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
